def _get_referenced_extras(markers: MarkerList) -> frozenset[NormalizedName]:
    """Collect all extra names referenced in a marker tree.

    Walks the parsed marker tree and returns a frozenset of canonicalized
    extra names that appear in any comparison involving the ``extra``
    variable or the ``extras`` membership test.
    """
    result: set[NormalizedName] = set()

    def _walk(items: MarkerList) -> None:
        for item in items:
            if isinstance(item, list):
                # Nested group (from & / | or parentheses)
                _walk(item)
            elif isinstance(item, tuple):
                # A comparison: (lhs, op, rhs)
                lhs, _op, rhs = item
                # Check if this comparison involves 'extra'
                lhs_is_extra = isinstance(lhs, Variable) and lhs.value == "extra"
                rhs_is_extra = isinstance(rhs, Variable) and rhs.value == "extra"
                if lhs_is_extra or rhs_is_extra:
                    # The other side holds the extra name as a Value
                    if lhs_is_extra:
                        name_node = rhs
                    else:
                        name_node = lhs
                    if isinstance(name_node, Value):
                        result.add(canonicalize_name(name_node.value))
            # "and" / "or" are MarkerLogical (strings) — skip them

    _walk(markers)
    return frozenset(result)
